{
  "book_code": "2ES",
  "verses": [
    {
      "text_ar": "لكنهم تآمروا فيما بينهم على أن يتركوا جمهور الأمم، ويمضوا إلى منطقة أبعد لم ينسكنها البشر من قبل،",
      "chapter": 13,
      "verse": 41
    },
    {
      "text_ar": "لكي يحفظوا هناك فرائضهم التي لم يحفظوها في أرضهم.",
      "chapter": 13,
      "verse": 42
    },
    {
      "text_ar": "وقد دخلوا عبر الممرات الضيقة لنهر الفرات.",
      "chapter": 13,
      "verse": 43
    },
    {
      "text_ar": "لأن العلي صنع حينئذ آيات لأجلهم، وأوقف ينابيع النهر حتى عبروا.",
      "chapter": 13,
      "verse": 44
    },
    {
      "text_ar": "لأنه كان في تلك البلاد طريق طويل ليُقطع، أعني سنة ونصفاً. وتُدعى تلك المنطقة أرض عزاريث.",
      "chapter": 13,
      "verse": 45
    },
    {
      "text_ar": "ثم أقاموا هناك حتى الزمان الأخير. والآن عندما يبدون في العودة مرة أخرى،",
      "chapter": 13,
      "verse": 46
    },
    {
      "text_ar": "فإن العلي يوقف ينابيع النهر مرة أخرى لكي يعبروا. ولذلك رأيت الجمهور مجتمعاً بسلام.",
      "chapter": 13,
      "verse": 47
    },
    {
      "text_ar": "أما الذين تبقوا من شعبك فهو أولئك الموجودون داخل تخومي المقدسة.",
      "chapter": 13,
      "verse": 48
    },
    {
      "text_ar": "لذلك سيكون أنه عندما يبيد جمهور الأمم المجتمعين، فإنه سيدافع عن الشعب الباقي.",
      "chapter": 13,
      "verse": 49
    },
    {
      "text_ar": "وحينئذ يريك عجائب كثيرة جداً».",
      "chapter": 13,
      "verse": 50
    },
    {
      "text_ar": "فقلت: «أيها السيد الرب، فسر لي هذا: لماذا رأيت الإنسان صاعداً من وسط البحر؟»",
      "chapter": 13,
      "verse": 51
    },
    {
      "text_ar": "فقال لي: «كما أنه لا يستطيع أحد أن يستقصي أو يعرف ما في أعماق البحر، هكذا لا يستطيع أحد على الأرض أن يرى ابني، أو أولئك الذين معه، إلا في وقت يومه.",
      "chapter": 13,
      "verse": 52
    },
    {
      "text_ar": "هذا هو تفسير الحلم الذي رأيته، ولهذا وحدك نلت الاستنارة بهذا،",
      "chapter": 13,
      "verse": 53
    },
    {
      "text_ar": "لأنك تركت طرقك الخاصة، واجتهدت في طرقي، وبحثت عن شريعتي.",
      "chapter": 13,
      "verse": 54
    },
    {
      "text_ar": "لقد رتبت حياتك بحكمة، ودعوت الفطنة أمك.",
      "chapter": 13,
      "verse": 55
    },
    {
      "text_ar": "لذلك أريتك هذا، لأن هناك مكافأة معدة لدى العلي. وسيكون أنه بعد ثلاثة أيام أخرى سأكلمك بأمور أخرى، وأعلن لك أموراً عظيمة وعجيبة».",
      "chapter": 13,
      "verse": 56
    },
    {
      "text_ar": "ثم خرجت وذهبت إلى الحقل، ومجدت وشكرت العلي جداً بسبب عجائبه التي صنعها شيئاً فشيئاً،",
      "chapter": 13,
      "verse": 57
    },
    {
      "text_ar": "وبسبب أنه يدبر الأزمنة، والأمور التي تحدث في مواسمها. وهكذا جلست هناك ثلاثة أيام.",
      "chapter": 13,
      "verse": 58
    }
  ]
}
